const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.0/projects/%7Bproject_id%7D/tools',
  qs: {
    'filters[is_active]': 'SOME_BOOLEAN_VALUE',
    for_mobile: 'SOME_BOOLEAN_VALUE',
    include_configurable_generic_tools: 'SOME_BOOLEAN_VALUE',
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/projects/%7Bproject_id%7D/tools?filters%5Bis_active%5D=SOME_BOOLEAN_VALUE&for_mobile=SOME_BOOLEAN_VALUE&include_configurable_generic_tools=SOME_BOOLEAN_VALUE&page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

const request = require('request');

const options = {
  method: 'PATCH',
  url: 'https://api.procore.com/rest/v1.0/projects/%7Bproject_id%7D/tools',
  headers: {'content-type': 'application/json'},
  body: {tools: [{id: 1, is_active: true, position: 3}]},
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Patch,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/projects/%7Bproject_id%7D/tools"),
    Content = new StringContent("{\"tools\":[{\"id\":1,\"is_active\":true,\"position\":3}]}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

